/*
# Migrate data from old database to new database

## What this does
- Copies 75 customer profiles from the old database (bolt-native-database-71560774)
  excluding phone 0778908989 which already exists in the new DB with a different ID
- Copies 5 approved drivers from the old database
- Uses ON CONFLICT (id) DO UPDATE to avoid duplicates
- Skips admin profiles (admin is already set up in the new database)
- Maps old role 'rider' to new role 'customer'

## Tables affected
- profiles: INSERT ... ON CONFLICT (id) DO UPDATE
- drivers: INSERT ... ON CONFLICT (id) DO UPDATE
*/

-- Insert customer profiles from old database (excluding phone 0778908989 which already exists)
ON CONFLICT (id) DO UPDATE SET
  phone = EXCLUDED.phone,
  name = EXCLUDED.name,
  role = EXCLUDED.role,
  rating = EXCLUDED.rating,
  total_rides = EXCLUDED.total_rides;

-- Insert drivers from old database
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  phone = EXCLUDED.phone,
  car_number = EXCLUDED.car_number,
  is_approved = EXCLUDED.is_approved,
  status = EXCLUDED.status,
  rating = EXCLUDED.rating,
  total_rides = EXCLUDED.total_rides;
